  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00185",
          "explanation": "Doctor corrected the misconception that all post-cleaning pain/wet dressing is infection while defining dangerous change.",
          "quote": "不一定是感染失控"
        },
        {
          "event_id": "lite_evt_00355",
          "explanation": "Doctor corrected the medication misconception and prevented self-application of old burn cream.",
          "quote": "旧的磺胺嘧啶银乳膏"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor repeatedly used plain language to correct misunderstandings about wet dressings/odor, fever absence or low-grade fever, and old sulfadiazine cream, and integrated those corrections into ED, inpatient, and discharge plans without blame.",
