        },
        {
          "event_id": "lite_evt_00098",
          "explanation": "Doctor handled cost/work barriers by prioritizing urgent treatment and delegating practical tasks to the spouse.",
          "quote": "请假的事让你老婆帮你跟单位说一声“急诊住院”"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor converted travel, cost, and leave concerns into practical steps: nearby ED, spouse accompaniment/support, bring records/medications, and do not delay urgent care for work or cost concerns.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
