      "citations": [
        {
          "event_id": "lite_evt_00011",
          "explanation": "Doctor immediately upgraded chills plus odor/wet dressing in a deep burn to an infection-risk problem rather than routine dressing advice.",
          "quote": "不能只当成“正常渗液”在线观察"
        },
        {
          "event_id": "lite_evt_00011",
          "explanation": "Doctor directed the trajectory toward same-day in-person evaluation.",
          "quote": "最好是今天就去"
        }
      ],
      "explanation": "RC1 was met because the initial response treated the presentation as possible infection progression and set a same-day care direction.",
      "issue_kind": "none",
